import React from 'react';
import { useNavigation, useDayPicker, CaptionProps } from 'react-day-picker';
import { isSameMonth } from 'date-fns';
import { ChevronLeft, ChevronRight } from '@hexa-ui/icons';
import { Container, Label } from './Caption.styles';
import { IconButton } from '../../../icon-button';

const Caption = (props: CaptionProps): JSX.Element => {
  const { displayMonth } = props;
  const { nextMonth, previousMonth, goToMonth, displayMonths } = useNavigation();
  const {
    locale,
    formatters: { formatCaption },
    numberOfMonths,
  } = useDayPicker();

  const displayIndex = displayMonths.findIndex((month) => isSameMonth(displayMonth, month));

  const isFirst = displayIndex === 0;
  const isLast = displayIndex === displayMonths.length - 1;

  const hideNext = numberOfMonths > 1 && (isFirst || !isLast);
  const hidePrevious = numberOfMonths > 1 && (isLast || !isFirst);

  const handlePreviousMonth = () => {
    if (!previousMonth) return;
    goToMonth(previousMonth);
  };

  const handleNextMonth = () => {
    if (!nextMonth) return;
    goToMonth(nextMonth);
  };

  return (
    <Container>
      {!hidePrevious && (
        <IconButton
          disabled={!previousMonth}
          data-testid="previous-calendar-month-button"
          type="button"
          variant="inherit"
          icon={() => <ChevronLeft size="medium" />}
          onClick={handlePreviousMonth}
        />
      )}
      <Label>{formatCaption(displayMonth, { locale })}</Label>
      {!hideNext && (
        <IconButton
          disabled={!nextMonth}
          data-testid="next-calendar-month-button"
          type="button"
          variant="inherit"
          icon={() => <ChevronRight size="medium" />}
          onClick={handleNextMonth}
        />
      )}
    </Container>
  );
};

export default Caption;
